// api/books.ts: written by hand, kept in sync by hope
import { useQuery } from '@tanstack/react-query'

export type Book = {
  id: string
  title: string
  status: 'available' | 'borrowed' | 'lost'
}

export function useBook(bookId: string) {
  return useQuery({
    queryKey: ['books', bookId], // match it in every invalidateQueries
    queryFn: async (): Promise<Book> => {
      const res = await fetch(`https://bookshelf.example/v1/books/${bookId}`)
      if (!res.ok) throw new Error(`GET /books/${bookId}: ${res.status}`)
      return res.json() // a promise, not a check
    },
  })
}

// BookPage.tsx
export function BookPage({ id }: { id: string }) {
  const book = useBook(id)
  return <h1>{book.data?.title}</h1>
}

