import { afterEach, beforeEach, expect, it } from 'vitest'
import { createBook, installMocks, mockOperation, resetMocks, seedFaker } from './gen/dev'
import { getBook, listBooks } from './gen'

beforeEach(() => {
  installMocks()
  seedFaker(42)
})
afterEach(() => resetMocks())

it('shows a lost book', async () => {
  const lost = createBook({ status: 'lost' })
  mockOperation('getBook', { json: lost })
  expect((await getBook({ params: { bookId: lost.id } })).status).toBe('lost')
})

it('survives a 404', async () => {
  mockOperation('getBook', { status: 404, json: { message: 'no such book' } })
  await expect(getBook({ params: { bookId: 'missing' } })).rejects.toMatchObject({ status: 404 })
})

it('lists from spec-derived fixtures', async () => {
  expect((await listBooks()).length).toBeGreaterThan(0)
})

import type { HttpMiddleware } from '@pyreon/http'
import { signal } from '@pyreon/reactivity'
import { configureApi } from './gen'

const token = signal('')

const retryOn401: HttpMiddleware = async (req, next) => {
  const res = await next(req)
  return res.status === 401 ? next(req) : res
}

configureApi({
  headers: () => ({ Authorization: `Bearer ${token()}` }),
  use: [retryOn401],
})
